package app.planaloud.voice;
import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.media.*;import android.os.*;import android.speech.RecognizerIntent;import android.text.InputType;import android.util.Base64;import android.widget.*;
import androidx.appcompat.app.AppCompatActivity;import com.google.android.material.button.MaterialButton;import org.json.*;
import java.io.*;import java.net.*;import java.nio.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;

/** Voice plugin entry point. Transcription fills the composer and never executes schedules. */
public final class MainActivity extends AppCompatActivity {
 @Override protected void attachBaseContext(android.content.Context base){super.attachBaseContext(app.planaloud.ui.UiScale.wrap(base));}

 private final ExecutorService worker=Executors.newSingleThreadExecutor();private volatile boolean recording,closed,recognize;private volatile AudioRecord microphone;private Spinner provider;private EditText endpoint,model,key,deepseekKey;private TextView status;private MaterialButton capture;private boolean settingsOnly;private volatile boolean processing;
 private SharedPreferences prefs(){return getSharedPreferences("settings",0);}private int selectedProvider(){return new int[]{3,0,1}[provider.getSelectedItemPosition()];}
 public void onCreate(Bundle saved){super.onCreate(saved);VoiceSettings.migrate(this);settingsOnly=getIntent().getBooleanExtra("settings_only",false);LinearLayout page=new LinearLayout(this);page.setOrientation(1);int pad=Math.round(20*getResources().getDisplayMetrics().density);page.setPadding(pad,pad,pad,pad);ScrollView scroll=new ScrollView(this);scroll.addView(page);setContentView(scroll);TextView title=new TextView(this);title.setText("语音识别模块");title.setTextSize(24);page.addView(title);
  LinearLayout config=new LinearLayout(this);config.setOrientation(1);config.setVisibility(settingsOnly?android.view.View.VISIBLE:android.view.View.GONE);button(page,"识别设置",()->config.setVisibility(config.getVisibility()==android.view.View.VISIBLE?android.view.View.GONE:android.view.View.VISIBLE));page.addView(config);provider=new Spinner(this);provider.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"DeepSeek 官方 ASR（默认）","系统语音识别","阿里云百炼 Qwen-ASR"}));provider.setSelection(prefs().getInt("voice_provider",3)==0?1:prefs().getInt("voice_provider",3)==1?2:0);config.addView(provider);endpoint=field(config,"百炼兼容API根地址",prefs().getString("voice_endpoint","https://dashscope.aliyuncs.com/compatible-mode/v1"));model=field(config,"语音模型",prefs().getString("voice_model","qwen3-asr-flash"));key=field(config,"独立语音API Key（不填写则使用Agent密钥）","");key.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);deepseekKey=field(config,"DeepSeek ASR API Key（当前Agent为官方DeepSeek时可留空）","");deepseekKey.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);
  TextView help=new TextView(this);help.setText("DeepSeek 使用官方语音识别接口，录音停止后上传，最长120秒。使用官方 DeepSeek 地址保存 AI 配置时会同时配置语音，通常无需再填密钥。识别结果先回填输入框，可编辑后发送。");config.addView(help);
  button(config,"保存识别设置",()->{try{save();toast("已保存语音配置");}catch(Exception e){error(e);}});
  status=new TextView(this);status.setText("录音结果先填入输入框，由你编辑后再发送给AI。");page.addView(status);capture=button(page,"开始语音输入",()->{if(recording){recognize=true;stopRecording();return;}if(processing)return;try{save();if(selectedProvider()==0){startActivityForResult(new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM).putExtra(RecognizerIntent.EXTRA_LANGUAGE,"zh-CN"),9);return;}if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},10);return;}startRecording();}catch(Exception e){error(e);}});button(page,"返回",this::finish);if(!settingsOnly)capture.post(capture::performClick);
 }
 private void save()throws Exception{String address=endpoint.getText().toString().trim();if(selectedProvider()==1){URI uri=new URI(address);if(!"https".equals(uri.getScheme())||uri.getHost()==null||uri.getRawUserInfo()!=null||uri.getRawQuery()!=null||uri.getRawFragment()!=null)throw new IOException("百炼语音API需要完整HTTPS地址");}prefs().edit().putInt("voice_provider",selectedProvider()).putString("voice_endpoint",address.replaceAll("/+$","")).putString("voice_model",model.getText().toString().trim()).apply();if(key.length()>0){Class.forName("app.planaloud.Secrets").getMethod("put",Context.class,String.class,String.class).invoke(null,this,"voice_api_key",key.getText().toString());key.setText("");}if(deepseekKey.length()>0){Class.forName("app.planaloud.Secrets").getMethod("put",Context.class,String.class,String.class).invoke(null,this,"deepseek_voice_api_key",deepseekKey.getText().toString().trim());deepseekKey.setText("");}}
 private String secret(String name)throws Exception{return (String)Class.forName("app.planaloud.Secrets").getMethod("get",Context.class,String.class).invoke(null,this,name);}
 private void startRecording()throws Exception{final int mode=selectedProvider();int buffer=Math.max(4096,AudioRecord.getMinBufferSize(16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT));AudioRecord recorder=new AudioRecord(MediaRecorder.AudioSource.MIC,16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT,buffer*2);if(recorder.getState()!=AudioRecord.STATE_INITIALIZED){recorder.release();throw new IOException("麦克风不可用");}microphone=recorder;processing=true;recording=true;recognize=false;capture.setText("停止录音并识别");status.setText(mode==3?"录音中，停止后上传到DeepSeek（最多2分钟）":"录音中，停止后上传到百炼（最多2分钟）");recorder.startRecording();worker.submit(()->{File wav=new File(getCacheDir(),"voice-input.wav");try{try(RandomAccessFile out=new RandomAccessFile(wav,"rw")){out.setLength(0);out.write(new byte[44]);byte[] bytes=new byte[4096];long total=0;while(recording&&total<16000*2*120){int n=recorder.read(bytes,0,(int)Math.min(bytes.length,16000L*2*120-total));if(n<0){if(!recording)break;throw new IOException("录音已中断");}if(n>0){out.write(bytes,0,n);total+=n;}}if(total>=16000*2*120)recognize=true;recording=false;header(out,(int)total);}finally{try{recorder.stop();}catch(Exception ignored){}recorder.release();microphone=null;}
   if(recognize&&!closed){runOnUiThread(()->{capture.setEnabled(false);status.setText(mode==3?"正在DeepSeek识别…":"正在百炼识别…");});String text=mode==3?deepseek(wav):cloud(wav);runOnUiThread(()->result(text));}
  }catch(Throwable e){if(!closed)runOnUiThread(()->error(e));}finally{wav.delete();recording=false;processing=false;if(!closed)runOnUiThread(()->{capture.setEnabled(true);capture.setText("开始语音输入");});}});}
 private void stopRecording(){recording=false;AudioRecord r=microphone;if(r!=null)try{r.stop();}catch(Exception ignored){}}
 private static void header(RandomAccessFile out,int size)throws Exception{ByteBuffer b=ByteBuffer.allocate(44).order(ByteOrder.LITTLE_ENDIAN);b.put("RIFF".getBytes(StandardCharsets.US_ASCII)).putInt(size+36).put("WAVEfmt ".getBytes(StandardCharsets.US_ASCII)).putInt(16).putShort((short)1).putShort((short)1).putInt(16000).putInt(32000).putShort((short)2).putShort((short)16).put("data".getBytes(StandardCharsets.US_ASCII)).putInt(size);out.seek(0);out.write(b.array());}
 private String deepseek(File wav)throws Exception{
  String token=secret("deepseek_voice_api_key");
  if(token.isEmpty()){
   URI agent=new URI(prefs().getString("api_url",""));
   if("https".equalsIgnoreCase(agent.getScheme())&&"api.deepseek.com".equalsIgnoreCase(agent.getHost()))token=secret("api_key");
  }
  return DeepSeekAsr.transcribe(wav,token);
 }
 private String cloud(File wav)throws Exception{String token=secret("voice_api_key");if(token.isEmpty())token=secret("api_key");if(token.isEmpty())throw new IOException("请配置百炼语音API Key");String data="data:audio/wav;base64,"+Base64.encodeToString(java.nio.file.Files.readAllBytes(wav.toPath()),Base64.NO_WRAP);JSONObject body=new JSONObject().put("model",prefs().getString("voice_model","qwen3-asr-flash")).put("stream",false).put("messages",new JSONArray().put(new JSONObject().put("role","user").put("content",new JSONArray().put(new JSONObject().put("type","input_audio").put("input_audio",new JSONObject().put("data",data)))))).put("asr_options",new JSONObject().put("language","zh"));HttpURLConnection connection=(HttpURLConnection)new URL(prefs().getString("voice_endpoint","")+"/chat/completions").openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(15000);connection.setReadTimeout(120000);connection.setRequestMethod("POST");connection.setDoOutput(true);connection.setRequestProperty("Authorization","Bearer "+token);connection.setRequestProperty("Content-Type","application/json");try{try(OutputStream out=connection.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}if(connection.getResponseCode()!=200)throw new IOException("百炼语音 HTTP "+connection.getResponseCode()+"，请检查地域、模型及密钥");try(InputStream in=connection.getInputStream()){ByteArrayOutputStream response=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(response.size()+n>1024*1024)throw new IOException("识别响应过大");response.write(buffer,0,n);}return new JSONObject(response.toString("UTF-8")).getJSONArray("choices").getJSONObject(0).getJSONObject("message").getString("content");}}finally{connection.disconnect();}}
 public void onRequestPermissionsResult(int code,String[] permissions,int[] grants){super.onRequestPermissionsResult(code,permissions,grants);if(code==10&&grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED)try{startRecording();}catch(Exception e){error(e);}}
 protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(result!=RESULT_OK||data==null)return;if(code==9){ArrayList<String> values=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(values!=null&&!values.isEmpty())result(values.get(0));}}
 private void result(String value){if(closed)return;if(value==null||value.trim().isEmpty()){toast("未识别到文字，请重试");return;}if(settingsOnly){status.setText("识别结果："+value);return;}setResult(RESULT_OK,new Intent().putExtra("voice_text",value.trim()));finish();}
 private void toast(String text){Toast.makeText(this,text,Toast.LENGTH_LONG).show();}private void error(Throwable e){String message=e.getMessage();status.setText(message==null?"识别未完成，请检查配置":message);capture.setText("开始语音输入");}
 private EditText field(LinearLayout page,String hint,String value){EditText edit=new EditText(this);edit.setHint(hint);edit.setText(value);edit.setTextSize(15);page.addView(edit);return edit;}
 private MaterialButton button(LinearLayout page,String title,Runnable action){MaterialButton b=new MaterialButton(this);b.setText(title);b.setOnClickListener(v->action.run());page.addView(b);return b;}
 protected void onPause(){super.onPause();if(recording){recognize=false;stopRecording();}}
 protected void onDestroy(){closed=true;recognize=false;stopRecording();worker.shutdownNow();super.onDestroy();}
}
